/**
 * health-scorer.ts —— 项目健康度评分引擎（纯函数）
 *
 * 设计哲学：确定性算法为骨干，4 维加权评分 + 规则化风险检测
 * 无 LLM 调用，零幻觉，所有扣分都有可追溯的数值依据
 *
 * 4 个维度（加权平均）：
 *   - 进度维度 (30%)：实际进度 vs 预期进度偏差
 *   - 排期维度 (30%)：临期/逾期任务占比
 *   - 负载维度 (20%)：资源过载率
 *   - 质量维度 (20%)：阻塞 + 取消率
 */
type TaskStatus = 'todo' | 'in_progress' | 'done' | 'blocked' | 'cancelled';
type TaskPriority = 'low' | 'medium' | 'high' | 'urgent';
interface ScoreTask {
    id: string;
    status: TaskStatus;
    progress: number;
    estimatedHours: number;
    actualHours?: number;
    dueDate?: Date;
    assigneeId?: string;
    priority: TaskPriority;
    createdAt: Date;
    updatedAt: Date;
}
interface ScoreDependency {
    id: string;
    fromTaskId: string;
    toTaskId: string;
    type: string;
    status: string;
}
interface ProjectInfo {
    id: string;
    startDate: Date;
    endDate: Date;
    totalTasks: number;
}
export interface HealthScoreInput {
    project: ProjectInfo;
    tasks: ScoreTask[];
    dependencies?: ScoreDependency[];
    now?: Date;
}
export interface HealthRisk {
    id: string;
    type: 'schedule_risk' | 'overload' | 'blocked_task' | 'dependency_deadlock' | 'scope_creep' | 'inactive';
    severity: 'low' | 'medium' | 'high' | 'critical';
    title: string;
    description: string;
    relatedTaskIds: string[];
    metric?: {
        name: string;
        value: number;
        threshold: number;
        unit: string;
    };
}
export interface HealthScoreResult {
    score: number;
    level: 'green' | 'yellow' | 'red';
    dimensions: {
        progress: number;
        schedule: number;
        workload: number;
        quality: number;
    };
    risks: HealthRisk[];
    suggestions: string[];
    computedAt: Date;
}
/** 计算健康度评分 */
export declare function calculateHealthScore(input: HealthScoreInput): HealthScoreResult;
export {};
